// First behavioural test for the docs site. Dependency-free: node:test only.
//
//   node --test qa/            (after landing; then `npm test`)
//
// Why it exists: .vitepress/config.mts sets `ignoreDeadLinks: true`, so a green
// `docs:build` proves nothing about internal links. These assertions can fail.
//
// LANDING (not done yet, the diff is frozen pending the 19 Nov approval):
//   git mv tmp/qa/test-docs-links.mjs qa/test-docs-links.mjs
//   package.json -> "scripts": { ..., "test": "node --test qa/" }

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs'
import { join, resolve } from 'node:path'

const CONFIG = '.vitepress/config.mts'

function findRoot(start = process.cwd()) {
  let dir = resolve(start)
  for (let i = 0; i < 4; i += 1) {
    if (existsSync(join(dir, CONFIG))) return dir
    const parent = resolve(dir, '..')
    if (parent === dir) break
    dir = parent
  }
  throw new Error(`cannot find ${CONFIG} at or above ${start}`)
}

const root = findRoot()
const configSource = readFileSync(join(root, CONFIG), 'utf8')

function markdownFiles(dir) {
  return readdirSync(join(root, dir), { withFileTypes: true }).flatMap((entry) => {
    const rel = `${dir}/${entry.name}`
    if (entry.isDirectory()) return markdownFiles(rel)
    return entry.name.endsWith('.md') ? [rel] : []
  })
}

function linksIn(source) {
  const links = []
  for (const match of source.matchAll(/\]\((\/[^)\s#]+)/g)) links.push(match[1])
  for (const match of source.matchAll(/link:\s*'(\/[^']*)'/g)) links.push(match[1])
  return links
}

// '/features/' -> 'features/index', '/guide/introduction' -> 'guide/introduction'
function slugOf(link) {
  const clean = link.split('#')[0].split('?')[0]
  const trailing = clean.endsWith('/')
  const path = clean.replace(/^\/+/, '').replace(/\/+$/, '')
  if (path === '') return 'index'
  return trailing ? `${path}/index` : path
}

function fileOf(slug) {
  const candidates = [join(root, `${slug}.md`), join(root, slug, 'index.md')]
  return candidates.find((p) => existsSync(p) && statSync(p).isFile()) ?? null
}

function globToRegExp(glob) {
  const escaped = glob.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*')
  return new RegExp(`^${escaped}$`)
}

const configLinks = [...configSource.matchAll(/link:\s*'(\/[^']*)'/g)].map((m) => m[1])

test('every nav and sidebar link resolves to a markdown file', () => {
  assert.ok(configLinks.length >= 30, `only ${configLinks.length} config links found`)
  const dead = configLinks.filter((link) => fileOf(slugOf(link)) === null)
  assert.deepEqual(dead, [], `dead links in ${CONFIG}: ${dead.join(', ')}`)
})

test('every published page is linked, or excluded from the build', () => {
  const pages = [...markdownFiles('features'), ...markdownFiles('guide')]
  const sources = [configSource, ...pages.map((page) => readFileSync(join(root, page), 'utf8'))]
  const targets = new Set(sources.flatMap(linksIn).map(slugOf))
  const excluded = [...configSource.matchAll(/srcExclude:\s*\[([^\]]*)\]/g)]
    .flatMap((match) => [...match[1].matchAll(/'([^']+)'/g)].map((q) => q[1]))
    .map(globToRegExp)
  const unreachable = pages.filter((page) => {
    if (excluded.some((re) => re.test(page))) return false
    return !targets.has(page.replace(/\.md$/, ''))
  })
  assert.deepEqual(
    unreachable,
    [],
    `reachable by no link and not in srcExclude: ${unreachable.join(', ')}`
  )
})

